/**
 * The server's diagnostics caps and its truncation marker, mirrored so a fixture can carry a
 * string that was **actually clamped** (story 10.10, AC-7).
 *
 * A fixture that sets `truncated: true` on a short, uncut `message` proves the renderer reads a
 * boolean. It does not prove the renderer survives a real clamp, and the two failures are
 * different: the second is the one where the marker is trimmed away by the layout, ellipsised by
 * CSS, or lost because the renderer clamps the already-clamped string a second time. So the
 * level-1 fixture is generated by running this clamp — the same arithmetic
 * `DiagnosticsBounder.clamp` runs — over a string that is genuinely over the cap.
 *
 * The caps are deployment configuration and ADR-002 §16.5 deliberately does **not** freeze them
 * in the contract as `maxLength`, so they cannot be read from `openapi.yaml`. They are pinned
 * instead: `diagnosticsBounds.test.ts` reads `backend/src/main/resources/application.yml` and
 * `DiagnosticsBounder.java` and fails if either drifts from the values below. Nothing here is a
 * round number somebody typed.
 */

/** `DiagnosticsBounder.TRUNCATION_MARKER`. */
export const TRUNCATION_MARKER = '…[truncated]';

/** `studio.compile.diagnostics.*` defaults. */
export const DIAGNOSTICS_CAPS = {
  maxPerStep: 10,
  maxMessageChars: 400,
  maxExcerptChars: 120,
  maxTotalBytes: 65536,
} as const;

/**
 * `DiagnosticsBounder.clamp`, character for character. A clamped value is exactly `max`
 * characters long and ends with the marker, so the marker's position is the server's, not one
 * chosen here.
 */
export function clampLikeBounder(value: string, max: number): string {
  if (value.length <= max) {
    return value;
  }
  if (max <= TRUNCATION_MARKER.length) {
    return value.substring(0, Math.max(0, max));
  }
  return value.substring(0, max - TRUNCATION_MARKER.length) + TRUNCATION_MARKER;
}

/** Builds a string long enough that the clamp must fire, without a magic number in the fixture. */
export function overCap(seed: string, cap: number): string {
  const repeated = seed.repeat(Math.ceil((cap * 2) / seed.length));
  return repeated.slice(0, cap * 2);
}
